package com.greatleyposhley.professy.collaboration;
import org.springframework.web.bind.annotation.RestControllerAdvice;import org.springframework.web.servlet.mvc.method.annotation.ResponseBodyAdvice;import org.springframework.core.MethodParameter;import org.springframework.http.*;import org.springframework.http.converter.HttpMessageConverter;import org.springframework.http.server.*;import tools.jackson.databind.ObjectMapper;import java.util.regex.*;
@RestControllerAdvice @org.springframework.core.annotation.Order(100)
public class TicketActorResponses implements ResponseBodyAdvice<Object>{private final TicketActors actors;private final WorkAccess access;private final ObjectMapper json;public TicketActorResponses(TicketActors actors,WorkAccess access,ObjectMapper json){this.actors=actors;this.access=access;this.json=json;}public boolean supports(MethodParameter type,Class<? extends HttpMessageConverter<?>> converter){return true;}public Object beforeBodyWrite(Object body,MethodParameter type,MediaType media,Class<? extends HttpMessageConverter<?>> converter,ServerHttpRequest request,ServerHttpResponse response){if(body==null)return body;Matcher path=Pattern.compile("^/api/(?:v1/)?(?:projects/[0-9]+/)?(epics|stories|tasks|issues|testcases)(?:/.*)?$").matcher(request.getURI().getPath());if(!path.matches())return body;return actors.enrich(json.valueToTree(body),access.kind(path.group(1)),actors.assignments());}}
